#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int c;
    /* Consome o restante da linha que contem o numero N */
    while ((c = getchar()) != EOF && c != '\n') { }

    long bal = 0;
    int valid = 1;

    for (int i = 0; i < n; i++) {
        /* Le a linha inteira caractere a caractere (lida com linhas vazias,
           espacos consecutivos e tamanho arbitrario) */
        while ((c = getchar()) != EOF && c != '\n') {
            if (c == '{') {
                bal++;
            } else if (c == '}') {
                bal--;
                if (bal < 0) {
                    /* Fechou sem abrir: invalido, mas continua lendo
                       para esgotar a entrada */
                    valid = 0;
                }
            }
        }
        if (c == EOF) break;
    }

    puts((valid && bal == 0) ? "S" : "N");
    return 0;
}
